<?php
if (!defined('ABSPATH')) { exit; }
final class SPF_Customers {
    public function hooks(){add_action('admin_post_spf_save_customer',[$this,'save']);add_action('admin_post_spf_delete_customer',[$this,'delete']);}
    private function authorize(){if(!current_user_can(SPF_Roles::CUSTOMERS)&&!current_user_can('manage_options')){wp_die(esc_html__('No tienes permisos para gestionar clientes.','sistema-para-farmacias'));}}
    private function redirect($notice,$type='success'){wp_safe_redirect(add_query_arg(['page'=>'spf-customers','spf_notice'=>$notice,'spf_notice_type'=>$type],admin_url('admin.php')));exit;}
    public function save(){ $this->authorize();check_admin_referer('spf_save_customer');global $wpdb;$table=SPF_Database::table('customers');$id=absint($_POST['customer_id']??0);$now=current_time('mysql');$allowed=array_merge(SPF_Config::person_documents(),SPF_Config::business_documents());if(!$allowed){$allowed=['GENERIC'=>__('Documento','sistema-para-farmacias')];}$document_type=sanitize_text_field(wp_unslash($_POST['document_type']??''));if(!isset($allowed[$document_type])){$document_type=(string)array_key_first($allowed);}$document_number=sanitize_text_field(wp_unslash($_POST['document_number']??''));$name=sanitize_text_field(wp_unslash($_POST['name']??''));$business_name=sanitize_text_field(wp_unslash($_POST['business_name']??''));if($name===''&&$business_name===''){$this->redirect('missing_name','error');}if($document_number!==''){$duplicate=$id?$wpdb->get_var($wpdb->prepare("SELECT id FROM $table WHERE document_number=%s AND id<>%d LIMIT 1",$document_number,$id)):$wpdb->get_var($wpdb->prepare("SELECT id FROM $table WHERE document_number=%s LIMIT 1",$document_number));if($duplicate){$this->redirect('duplicate_document','error');}}$data=['document_type'=>$document_type,'document_number'=>$document_number,'name'=>$name?:$business_name,'business_name'=>$business_name,'address'=>sanitize_textarea_field(wp_unslash($_POST['address']??'')),'email'=>sanitize_email(wp_unslash($_POST['email']??'')),'phone'=>sanitize_text_field(wp_unslash($_POST['phone']??'')),'updated_at'=>$now];if($id){$wpdb->update($table,$data,['id'=>$id]);}else{$data['created_at']=$now;$wpdb->insert($table,$data);}$this->redirect($id?'updated':'created'); }
    public function delete(){ $this->authorize();check_admin_referer('spf_delete_customer');global $wpdb;$id=absint($_POST['customer_id']??0);$sales=SPF_Database::table('sales');$customers=SPF_Database::table('customers');if($id<=0){$this->redirect('invalid','error');}$used=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $sales WHERE customer_id=%d",$id));if($used>0){$this->redirect('customer_used','error');}$wpdb->delete($customers,['id'=>$id]);$this->redirect('deleted'); }
}
